<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Quote\Item;
use HardnessMcp\Context\ExecutionContext; use HardnessMcp\Tools\{ToolDefinition,ToolExecutionResult,ToolInterface};
final class QuoteItemAddTool implements ToolInterface {
 private QuoteItemGatewayInterface $gateway; public function __construct(QuoteItemGatewayInterface $gateway){$this->gateway=$gateway;}
 public function getDefinition():ToolDefinition{return new ToolDefinition('hardness.quote_item.add','Adds one or more products exclusively to exactly one explicitly chosen pending quote. The user must identify one specific quote_id. Never choose a quote, select a pending or most recent quote, distribute items across quotes, or turn one request into additions to multiple quotes. A list is permitted only when every product and quantity was explicitly supplied by the user for that same quote_id. Prices are calculated automatically by the ERP; this Tool never accepts a manual price or discount. An item may include location_code when the user explicitly supplies the ERP Ambiente for that item. location_code is optional: never ask for it merely because it was omitted. If the user has not chosen one specific quote, ask which quote must be changed before calling this Tool. Do not automatically retry a result marked indeterminate or requires_quote_review.', ['type'=>'object','properties'=>['quote_id'=>['type'=>'integer','minimum'=>1],'items'=>['type'=>'array','minItems'=>1,'maxItems'=>100,'items'=>['type'=>'object','properties'=>['product_id'=>['type'=>'integer','minimum'=>1],'quantity'=>['type'=>'number','exclusiveMinimum'=>0],'location_code'=>['type'=>'string','minLength'=>1,'maxLength'=>60]],'required'=>['product_id','quantity'],'additionalProperties'=>false]]],'required'=>['quote_id','items'],'additionalProperties'=>false],['quote:item:add'],true);}
 public function execute(array $a,ExecutionContext $c):ToolExecutionResult { try{$r=$this->gateway->add($a,$c);}catch(\Throwable $e){return $this->error($e->getMessage(),$a);} $failed=(string)($r['status']??'')!=='completed'; $text=$failed?'A inclusão foi interrompida; confira o resultado de cada item.':'Itens incluídos no orçamento.'; $result=['content'=>[['type'=>'text','text'=>$text]],'structuredContent'=>$r,'isError'=>$failed]; $code=$this->failureCode($r); return new ToolExecutionResult($result,$failed?'tools_call_quote_item_add_failed':'tools_call_quote_item_add',$failed?$code:null); }
 private function error(string $code,array $a):ToolExecutionResult{$items=[];foreach(($a['items']??[]) as $i=>$item)if(is_array($item))$items[]=['index'=>$i+1,'product_id'=>(int)($item['product_id']??0),'requested_quantity'=>$item['quantity']??0,'status'=>'not_attempted'];$safe=in_array($code,['quote_unavailable','quote_not_pending','quote_item_retryable','quote_item_unavailable'],true)?$code:'quote_item_add_failed';return new ToolExecutionResult(['content'=>[['type'=>'text','text'=>'Não foi possível incluir os itens no orçamento.']],'structuredContent'=>['quote_id'=>(int)($a['quote_id']??0),'status'=>'failed','items'=>$items,'error'=>['code'=>$safe]]], 'tools_call_quote_item_add_failed',$safe);}
 private function failureCode(array $r):string{foreach(($r['items']??[]) as $item)if(is_array($item)&&isset($item['error_code'])&&is_string($item['error_code']))return $item['error_code'];return (string)($r['error_code']??'quote_item_add_failed');}
}
